package com.subhamviky.settlement.generated;

import java.util.Map;
import java.util.Optional;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/**
 * settlement-service — application service (generated by A2C CodeGenAgent).
 * The single public entry point handle() applies every mandatory NFR:
 * idempotency per requestId, circuit breaker + retry with backoff, logging
 * and tracing, a health probe and graceful shutdown. Domain logic belongs
 * in process().
 */
@Service
public class SettlementServiceService {

    private static final Logger logger = LoggerFactory.getLogger(SettlementServiceService.class);
    private final NfrSupport.IdempotencyStore store;
    private final NfrSupport.CircuitBreaker breaker = new NfrSupport.CircuitBreaker(5, 30_000);
    private volatile boolean accepting = true;

    public SettlementServiceService() {
        this(new NfrSupport.InMemoryIdempotencyStore());
    }

    public SettlementServiceService(NfrSupport.IdempotencyStore store) {
        this.store = store;
        NfrSupport.registerGracefulShutdown(this::shutdown);
    }

    /** Single public entry point. */
    public Map<String, Object> handle(String requestId, String tenantId, Map<String, Object> payload) {
        if (!accepting) {
            throw new IllegalStateException("service is shutting down");
        }
        return Observability.traced("settlement-service.handle", () -> {
            Optional<Map<String, Object>> replay = store.result(tenantId, requestId);
            if (replay.isPresent()) {
                return replay.get();
            }
            if (!store.claim(tenantId, requestId)) {
                throw new IllegalStateException("duplicate in flight: " + requestId);
            }
            try {
                Map<String, Object> result = NfrSupport.retryWithBackoff(() -> process(payload), breaker, 3, 50);
                store.complete(tenantId, requestId, result);
                return result;
            } catch (RuntimeException e) {
                store.release(tenantId, requestId);
                throw e;
            }
        });
    }

    public Map<String, Object> health() {
        return Map.of("path", NfrSupport.HEALTH_PATH, "status", accepting ? "UP" : "DRAINING",
                "circuit", breaker.state());
    }

    public void shutdown() {
        accepting = false;
        logger.info("graceful shutdown: no longer accepting work");
    }

    /** Replace with the domain logic of settlement-service. */
    protected Map<String, Object> process(Map<String, Object> payload) {
        return Map.of("accepted", true, "payload", payload);
    }
}
